INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷85·晋少帝本纪·开运三年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c7d707f140aeeb6d7f8cb666674b4e39a39263b6/content/books/zizhi-tongjian/vol-285/year-0946/part-06/sources/library/jiuwudaishi-085-946-december/source.txt", "note": "《旧五代史》卷85·晋少帝本纪·开运三年十二月，段落 jiu-wudaishi-205deb4a7860-p002047；已回查正文卷号、传主与上下文，纸本及异文待核。", "id": "8477d7d0-42dd-56cb-92cf-7752d47cdc14"}, {"title": "辽史·卷76·张砺传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7d3fe25/content/books/zizhi-tongjian/vol-281/year-0937/part-02/sources/library/liaoshi-076-zhang-li/source.txt", "note": "《辽史》卷76·张砺传，段落 liaoshi-7cd182a20e67-p005119；已核上下文及传主，纸本及异文待核。", "id": "36f6b4da-d6d1-52e8-81a9-d5a8aef7457e"}, {"title": "资治通鉴·卷285·开运三年·十二月晋军降契丹", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c7d707f140aeeb6d7f8cb666674b4e39a39263b6/content/books/zizhi-tongjian/vol-285/year-0946/part-06/sources/library/tongjian-285-946-surrender-camp/source.txt", "note": "《资治通鉴》卷285·开运三年·十二月晋军降契丹，段落 zizhi-tongjian-a63549944a71-p003390；已回查正文卷号、传主与上下文，纸本及异文待核。", "id": "2f033685-b48d-5486-8f41-853be4d1b929"}, {"title": "资治通鉴·卷285·开运三年·十二月南进及京城前后", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c7d707f140aeeb6d7f8cb666674b4e39a39263b6/content/books/zizhi-tongjian/vol-285/year-0946/part-06/sources/library/tongjian-285-946-surrender-capital/source.txt", "note": "《资治通鉴》卷285·开运三年·十二月南进及京城前后，段落 zizhi-tongjian-a63549944a71-p003391；已回查正文卷号、传主与上下文，纸本及异文待核。", "id": "3681fa21-0224-54a3-9d77-213b1dbabd97"}, {"title": "新五代史·卷9·晋本纪·开运三年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c7d707f140aeeb6d7f8cb666674b4e39a39263b6/content/books/zizhi-tongjian/vol-285/year-0946/part-06/sources/library/xinwudaishi-009-946/source.txt", "note": "《新五代史》卷9·晋本纪·开运三年，段落 xin-wudaishi-b08f244b9241-p000337；已回查正文卷号、传主与上下文，纸本及异文待核。", "id": "90a0bab8-962e-598e-a354-e5da6a3522fe"}, {"title": "资治通鉴·卷285·开运三年·十一月至十二月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/11bd80a1278ae2081bb275997aefcffa5b947ddc/content/books/zizhi-tongjian/vol-285/year-0946/part-05/sources/library/tongjian-285-946-november-december/source.txt", "note": "《资治通鉴》卷285·开运三年·十一月至十二月及追述，段落 zizhi-tongjian-a63549944a71-p003389；已回查正文卷题及上下文，纸本及异文待核。", "id": "149d5af8-e38f-5998-bd0d-c6615aa24a62"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "关勋", "aliases": ["關勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋军将。946年十二月丁巳朔，李谷让他快马送密奏，己未晚间到达朝廷。生卒年未载。与阁门使高勋姓名不同，不因勋字相同合并。", "biography": null, "status": "draft", "id": "3e379646-16e5-5876-8ec6-da41de1c524e"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "张祚", "aliases": ["張祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杜重威的从者。946年十二月辛酉等奉派向朝廷告急，返回军中时被契丹俘获，随后朝廷与前线消息中断。生卒年未载。", "biography": null, "status": "draft", "id": "026c1dec-c6ad-5b14-bd90-f7f38a410dce"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "李彦韬（后晋宣徽使）", "aliases": ["李彥韜（後晉宣徽使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，早年曾侍奉阎宝，后来入石敬瑭帐下并留在太原侍奉石重贵。945年任宣徽北院使、暂代侍卫马步都虞候，与冯玉争桑维翰的权力。与早期曾名李彦韬的温韬分档，温韬在后唐明宗时已被赐死。生卒年本段未载。", "biography": null, "status": "draft", "id": "e4ac4a2d-843f-5686-98da-4b16e23f906d"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "王清", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国军都虞候，曲周人。942年襄州久围未克时劝高行周加紧进攻，并与刘词率军先登。生卒年未载。", "biography": null, "status": "draft", "id": "ba8c58db-075d-59e6-967b-056db790e06a"}, {"name": "宋彦筠", "aliases": ["宋彥筠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋前同州节度使，滑州人。941年十一月丁丑受任高行周的副将，参与南面军前讨伐安从进的部署。生卒年未载。", "biography": null, "status": "draft", "id": "a66a316a-5777-5c2c-aaa8-0e523f85477d"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "高勋", "aliases": ["高勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋阁门使。946年十二月丙寅，杜重威派他向契丹送降表，耶律德光赐诏接受。与军将关勋分别识别；生卒年本批未核。", "biography": null, "status": "draft", "id": "ea4f636d-1bb8-5b40-a94d-0da7caf7ebea"}, {"name": "王周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王周。", "biography": null, "status": "draft", "id": "dcf3a493-1cbc-5185-9787-8041333d1d90"}, {"name": "王晖（后晋代州刺史）", "aliases": ["王暉（後晉代州刺史）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。946年十二月契丹派兵袭代州，他以城投降。与已录后蜀前陵州刺史王晖是否同人未证，暂分档；生卒年未载。", "biography": null, "status": "draft", "id": "33fc3f7d-b591-5611-9686-3873111a9d93"}, {"name": "郭璘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 946, "description": "邢州人，后晋易州刺史。曾屡次坚守易州抵抗契丹；946年十二月杜重威投降后，契丹派耿崇美诱使易州守军投降，郭璘无法制止并被杀。出生年未载。", "biography": null, "status": "draft", "id": "68257114-efe7-5bc0-8bfa-460ee44cfe10"}, {"name": "耿崇美", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十二月杜重威降后，奉命到易州诱说守军投降，并杀死刺史郭璘。生卒年未载。", "biography": null, "status": "draft", "id": "60458ef5-e4bc-5d29-b338-25090e903595"}, {"name": "李殷", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟人，后晋义武节度使。946年六月受任北面行营步军都指挥使兼都排阵使。生卒年未载；与后周王殷分为不同主体。", "biography": null, "status": "draft", "id": "bfab47cb-1a5c-5497-982a-5bf911264b2b"}, {"name": "方太", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：方太，讨平军乱者。", "biography": null, "status": "draft", "id": "f3df25e6-d0a6-57cc-8996-e5d57af4f5ef"}, {"name": "孙方简", "aliases": ["孫方簡", "孙方谏", "孫方諫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》称中山人，聚众于狼山，归附后晋后任东北招收指挥使，后来转投契丹并拘执刘延翰。《宋史》孙行友传写作孙方谏，记他是孙行友的兄子；《资治通鉴》记孙行友是其弟，亲属记载冲突待核。姓名字形与主体按狼山、职衔和事迹对应复用，生卒年未核。", "biography": null, "status": "draft", "id": "17e0109c-1d9d-5437-a7d0-5c7be7b6beb8"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "马崇祚", "aliases": ["馬崇祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹客省副使。946年十二月各地晋将投降后，耶律德光让他暂掌恒州事务。生卒年未载。", "biography": null, "status": "draft", "id": "58168672-d1e3-527b-8cfa-55d36f054d1d"}, {"name": "张砺", "aliases": ["張礪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张砺。", "biography": null, "status": "draft", "id": "9f51ea48-71ce-5c98-a3af-c7854041f72f"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "傅住儿", "aliases": ["傅住兒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十二月耶律德光派张彦泽领二千骑先取大梁，让傅住儿任都监。姓名展示用简体儿，原文傅住兒保留；生卒年本批未核。", "biography": null, "status": "draft", "id": "12d197f3-4308-5bdc-8f6b-0f011bde8459"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

